import { Col, Form, Row, Divider } from 'antd'
import React from 'react'
import { injectIntl } from 'react-intl'
import IntlMessages from '../../components/utility/intlMessages'
import ClaimList from '../../image/claim-list.png'
import ClaimForm from '../../image/claim-form.png'
import GojekStyled from './gojek.style'

class GojekPassenger extends React.Component {
  state = {
    product: ''
  };

  componentDidMount () {
    let product
    if (this.props.history && this.props.history.location && this.props.history.location.pathname) {
      product = this.props.history.location.pathname === '/go-driver/claim' ? 'go-driver' : 'gojek-passenger'
    }
    this.setState({ product })
  }

  goToClaimlist = () => {
    const { history } = this.props
    history.push('/?source=claim')
  };

  goToClaimForm = () => {
    this.props.history.push(`/${this.state.product}/claim-form`)
  };

  render () {
    return (
      <div>
        <GojekStyled>
          <Row type='flex' justify='center'>
            <Col xs={24} sm={24} md={12} lg={12} xl={12}>
              <label>
                <strong>
                  <IntlMessages id='Silakan pilih salah satu opsi dibawah yang Anda inginkan' />
                </strong>
              </label>
              <Divider className='divider' />
              <Row type='flex' justify='space-around'>
                <Col xs={24} sm={24} md={10} lg={10} xl={10}>
                  <div className='button-wrapper make-claim_color' onClick={this.goToClaimForm}>
                    <img src={ClaimForm} className='claim-img' alt='' />
                    <strong>
                      <IntlMessages id='Buat klaim baru' />
                    </strong>
                  </div>
                </Col>
                <Col xs={24} sm={24} md={10} lg={10} xl={10}>
                  <div className='button-wrapper claim-status_color' onClick={this.goToClaimlist}>
                    <img src={ClaimList} className='claim-img' alt='' />
                    <strong>
                      <IntlMessages id='Cek status klaim saya' />
                    </strong>
                  </div>
                </Col>
              </Row>
            </Col>
          </Row>
        </GojekStyled>
      </div>
    )
  }
}

const GojekPassengerWrapped = Form.create()(GojekPassenger)

export default injectIntl(GojekPassengerWrapped)
